package com.tjetc.config;

import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.RequestMapping;

/**
 * Forward all non-static, non-API requests to index.html so the SPA router can handle them.
 */
@Controller
public class SpaRedirectController {

    @RequestMapping(value = {"/{path:[^\.]*}", "/**/{path:[^\.]*}"})
    public String forward() {
        // Forward to index.html (located in static resources) which bootstraps the SPA
        return "forward:/index.html";
    }
}

package com.tjetc.controller;

import com.tjetc.domain.Orders;
import com.tjetc.domain.TrainTickets;
import com.tjetc.mq.OrderProducer;
import com.tjetc.mq.dto.OrderMessage;
import com.tjetc.service.OrderService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.Collections;
import java.util.List;

@RestController
@RequestMapping("/orders")
@Slf4j
public class OrdersControler {
    @Autowired
    OrderService orderService;

    @Autowired(required = false)
    private OrderProducer orderProducer;

    @RequestMapping("/list")
    public List<Orders> list(@RequestParam(name = "userId",required = false)Integer userId,
                             @RequestParam(name = "status",defaultValue = "")String  status){
        // 原: [Orders] list request...
        log.info("[订单] 查询订单列表，userId={}，status='{}'", userId, status);
        List<Orders> res = orderService.list(userId,status);
        // 原: [Orders] list response...
        log.info("[订单] 查询结果数量={}", res == null ? 0 : res.size());
        return res;
    }
    @RequestMapping("/del")
    public com.tjetc.vo.Result deleteById(Integer id){
        log.info("[订单] 删除订单请求，id={}", id);
        int r = orderService.deleteById(id);
        log.info("[订单] 删除订单结果，影响行数={}", r);
        if (r > 0) {
            java.util.HashMap<String, Object> data = new java.util.HashMap<>();
            data.put("rows", r);
            data.put("id", id);
            return new com.tjetc.vo.Result(200, "删除成功", data);
        }
        return com.tjetc.vo.Result.error(500, "删除失败");
    }

    @RequestMapping("/save")
    public com.tjetc.vo.Result save(@RequestParam(name = "userId") Integer userId, TrainTickets trainTickets,
                       @RequestParam(name = "passengers")String passengers,
                       @RequestParam(name = "price")Integer price){
        Integer ticketId = (trainTickets == null ? null : trainTickets.getId());
        // 原: [Orders] save request...
        log.info("[订单] 下单请求，userId={}，ticketId={}，乘客参数='{}'，价格={}", userId, ticketId, passengers, price);

        String orderId = orderService.save(userId,trainTickets,passengers,price);
        if("失败".equals(orderId)){
            // 原: [Orders] save failed...
            log.warn("[订单] 下单失败，userId={}，ticketId={}", userId, ticketId);
            return com.tjetc.vo.Result.error(500,"下单失败");
        }

        // 下单成功后，向 MQ 发一条消息（非致命：MQ 异常不影响订单落库）
        try {
            if (orderProducer == null) {
                // 原: [Orders] MQ producer not available...
                log.warn("[订单] MQ发送器不可用，跳过发送消息。orderId={}", orderId);
            } else {
                // passengers 入参格式可能是 "[1,2]" 或 "1,2"，先转为 Long 列表
                java.util.List<Long> passengerIds = new java.util.ArrayList<>();
                if (passengers != null && !passengers.trim().isEmpty()) {
                    String tmp = passengers.trim().replace("[", "").replace("]", "").replace("\"", "");
                    for (String p : tmp.split(",")) {
                        String s = p.trim().replaceAll("[^0-9]", "");
                        if (s.isEmpty()) continue;
                        passengerIds.add(Long.valueOf(s));
                    }
                }
                OrderMessage msg = new OrderMessage(
                        userId == null ? null : userId.longValue(),
                        ticketId == null ? null : ticketId.longValue(),
                        passengerIds.isEmpty() ? Collections.emptyList() : passengerIds,
                        price == null ? 0.0 : price.doubleValue()
                );
                // 原: [Orders] MQ publish start...
                log.info("[订单] MQ发送开始，exchange={}，routingKey={}，orderId={}，ticketId={}，乘客数={}",
                        com.tjetc.mq.RabbitMQConfig.ORDER_EXCHANGE,
                        com.tjetc.mq.RabbitMQConfig.ORDER_ROUTING_KEY,
                        orderId,
                        ticketId,
                        msg.getPassengerIds() == null ? 0 : msg.getPassengerIds().size());
                orderProducer.sendOrder(msg);
                // 原: [Orders] MQ publish success...
                log.info("[订单] MQ发送成功，orderId={}", orderId);
            }
        } catch (Exception e) {
            // 原: [Orders] MQ publish failed...
            log.error("[订单] MQ发送失败（已忽略，不影响下单落库），orderId={}，原因={} ", orderId, e.getMessage(), e);
        }

        // 原: [Orders] save success...
        log.info("[订单] 下单成功，orderId={}，userId={}，ticketId={}", orderId, userId, ticketId);
        java.util.HashMap<String,Object> data = new java.util.HashMap<>();
        data.put("orderId",orderId);
        data.put("totalPrice",price);
        data.put("status","待支付");
        return new com.tjetc.vo.Result(200,"下单成功，订单号：" + orderId, data);
    }

}

